  '18-or-21-karat': { w: 1536, h: 1024, top: '#E1D9CF', bottom: '#DAD2C8' },
  'bazu-cuff': { w: 1536, h: 1024, top: '#E5DFDA', bottom: '#D0C7C0' },
  'bracelets': { w: 1536, h: 1024, top: '#E2DBD5', bottom: '#D2C6BA' },
  'craft-hands': { w: 1312, h: 1199, top: '#352518', bottom: '#352517' },
