  'halgheh-hoop': { w: 1536, h: 1024, top: '#F0ECE8', bottom: '#E1D7CD' },
  'hero-necklace': { w: 1024, h: 1536, top: '#F4EFEB', bottom: '#E0D6CD' },
  'mehr-signet': { w: 1374, h: 1145, top: '#EEEAE6', bottom: '#D6CFC8' },
