  'rings': { w: 1536, h: 1024, top: '#D5CBC2', bottom: '#CDC2B8' },
  'sepid-pendant': { w: 1402, h: 1122, top: '#DAD1C6', bottom: '#D0C7BD' },
  'shabnam-drop': { w: 1374, h: 1145, top: '#F4F0EB', bottom: '#DCD2C9' },
